values
  ('fd4d4dab-abc2-4438-b998-4c0a757c25c5', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Professional role, ethics, informed consent, and testing workflow', 'Assessment is a professional service, not a collection of random tests. This section establishes the ethical, logistical, and documentation habits that make testing safe, useful, and defensible.', 0),
  ('5a07fe6c-9226-42fc-80f5-13b962657a4d', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'fd4d4dab-abc2-4438-b998-4c0a757c25c5', 'subtopic'::public.curated_course_node_type, 'Professional scope and ethical practice', 'Students learn what fitness assessors can responsibly measure, explain, document, and refer without drifting into diagnosis.', 0),
