  ('d714cb4b-acf3-428a-9cd5-b34193a3fb5c', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5a07fe6c-9226-42fc-80f5-13b962657a4d', 'concept'::public.curated_course_node_type, 'Confidentiality, privacy, data security, and respectful documentation', null, 1),
