  ('75330659-212d-45cd-9685-a0012f73fcb8', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5a07fe6c-9226-42fc-80f5-13b962657a4d', 'concept'::public.curated_course_node_type, 'Bias awareness, nonstigmatizing language, and body-respectful practice', null, 3),
  ('278a41df-a741-47ff-b921-b8b4848aec6d', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'fd4d4dab-abc2-4438-b998-4c0a757c25c5', 'subtopic'::public.curated_course_node_type, 'Testing workflow and standardization', 'The point is to reduce noise and error so results reflect the client rather than sloppy procedure.', 1),
