  ('7de7363b-f9e4-440b-a02e-b1b513e511a4', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '278a41df-a741-47ff-b921-b8b4848aec6d', 'concept'::public.curated_course_node_type, 'Equipment calibration, environmental conditions, and standardized scripts', null, 2),
  ('34ded138-9a87-4530-9089-a08c5a09c607', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '278a41df-a741-47ff-b921-b8b4848aec6d', 'concept'::public.curated_course_node_type, 'Recording forms, units, retest conditions, and quality-control habits', null, 3),
  ('3d858841-966c-4317-80e4-1113c9cc2285', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Health appraisal, preparticipation screening, contraindications, referral, and emergency response', 'The first assessment decision is whether and how to test safely. This section trains students to screen risk, identify red flags, and know when referral or modified testing is required.', 1),
