  ('8b8d0c21-d8bf-43ec-a08b-5d3307ca59c9', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '1440b4ba-39f5-4777-b473-bf28e01dfc52', 'concept'::public.curated_course_node_type, 'Risk stratification, medical clearance, and documentation of screening decisions', null, 3),
  ('af76dcbe-f7c3-47f4-9a5d-f4cd6dae7682', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '3d858841-966c-4317-80e4-1113c9cc2285', 'subtopic'::public.curated_course_node_type, 'Contraindications, referral, and emergency readiness', 'The gist is to prepare for foreseeable risk before testing begins.', 1),
  ('48544035-2f57-4011-bcba-7d616e8ee50b', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'af76dcbe-f7c3-47f4-9a5d-f4cd6dae7682', 'concept'::public.curated_course_node_type, 'Absolute and relative contraindications to exercise testing', null, 0),
