  ('11a7aa6f-caa9-428d-92b7-ca0e33e72df2', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'af76dcbe-f7c3-47f4-9a5d-f4cd6dae7682', 'concept'::public.curated_course_node_type, 'Emergency action plans, AED location, first aid, and communication roles', null, 2),
  ('2c017a3d-e502-43dd-8b6c-ed865f34281e', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'af76dcbe-f7c3-47f4-9a5d-f4cd6dae7682', 'concept'::public.curated_course_node_type, 'Referral language and handoff to healthcare professionals', null, 3),
  ('cecdd1ec-85e4-45fa-96b6-11b7662226fe', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Resting measures and cardiovascular assessment', 'Resting measures provide context for exercise testing and risk decisions. This section teaches students to gather basic cardiovascular data accurately and interpret it within scope.', 2),
