  ('5da62756-2f92-4fc8-8e03-c7658c92a2b4', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '254b9719-c0b0-4406-9663-4ca21f78acc1', 'concept'::public.curated_course_node_type, 'Measurement conditions, sources of error, and documentation', null, 3),
  ('8f0c7e74-7a41-42ac-9260-db4bd4aba9e0', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'cecdd1ec-85e4-45fa-96b6-11b7662226fe', 'subtopic'::public.curated_course_node_type, 'Cardiovascular interpretation and monitoring', 'The point is to recognize normal, abnormal, and uncertain responses without overclaiming.', 1),
  ('858189cc-9e86-47c5-9663-a6b0359d0d95', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '8f0c7e74-7a41-42ac-9260-db4bd4aba9e0', 'concept'::public.curated_course_node_type, 'Blood pressure categories and exercise readiness implications', null, 0),
