  ('c4c577cf-8d91-4a29-9e5e-8f0ca60c8b5d', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '8f0c7e74-7a41-42ac-9260-db4bd4aba9e0', 'concept'::public.curated_course_node_type, 'Rate of perceived exertion and symptom monitoring', null, 2),
  ('250c397b-5322-4ace-9d1b-42af8c863505', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '8f0c7e74-7a41-42ac-9260-db4bd4aba9e0', 'concept'::public.curated_course_node_type, 'Referral thresholds and communication of concerning findings', null, 3),
  ('7013f182-91be-4273-b39a-667564fa6082', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Cardiorespiratory fitness testing and aerobic capacity interpretation', 'Cardiorespiratory fitness is one of the strongest health-related fitness indicators. This section covers practical protocols and careful interpretation for varied settings.', 3),
  ('43847ca4-1693-435d-b94e-73dc1100fe34', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '7013f182-91be-4273-b39a-667564fa6082', 'subtopic'::public.curated_course_node_type, 'Aerobic testing protocols', 'Students learn to select protocols that match the client, setting, equipment, and risk level.', 0),
  ('64e9aabf-95e9-4e96-a143-deceac6d2de1', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '43847ca4-1693-435d-b94e-73dc1100fe34', 'concept'::public.curated_course_node_type, 'Field tests such as walk, step, shuttle, and timed-distance tests', null, 0),
