  ('0159289c-0d7b-4e8b-bb7b-c9aea1f83d64', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '43847ca4-1693-435d-b94e-73dc1100fe34', 'concept'::public.curated_course_node_type, 'Warm-up, termination criteria, recovery, and monitoring procedures', null, 3),
  ('071fb539-3005-4224-823d-2b0dd3077fa4', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '7013f182-91be-4273-b39a-667564fa6082', 'subtopic'::public.curated_course_node_type, 'VO2, intensity, and interpretation', 'The gist is to translate test data into useful fitness estimates and training zones while respecting protocol limits.', 1);
