  ('76adbecb-5b88-4751-b189-62927f204af6', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Body composition assessment and anthropometric methods', 'Body composition assessment can inform health and performance, but it is also easy to misuse. This section emphasizes measurement quality, limitations, and respectful communication.', 4),
