  ('a1812b84-8c18-4159-b6cb-f4f72bf7a359', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '76adbecb-5b88-4751-b189-62927f204af6', 'subtopic'::public.curated_course_node_type, 'Interpretation and communication', 'The point is to communicate body-composition information without shame, overprecision, or unsupported health claims.', 1),
