  ('f8938c26-a45e-49d9-a4aa-5f89f0cfb1ed', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'a1812b84-8c18-4159-b6cb-f4f72bf7a359', 'concept'::public.curated_course_node_type, 'Client-centered language and alternatives when testing is inappropriate', null, 3),
  ('6a0b3174-68fe-4aa4-9790-1e3d74327560', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Muscular strength, endurance, and power assessment', 'Muscular fitness supports health, function, performance, and injury resilience. This section teaches students to test strength qualities safely and choose measures that fit the goal.', 5),
