  ('cee76628-9233-47b7-984b-2630c3c1f538', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5994b2bc-bf5c-4c6d-9b3f-fba7e9359c31', 'concept'::public.curated_course_node_type, 'Reliability, learning effects, fatigue, and retest consistency', null, 3),
  ('4721a20f-a82f-49fb-bf0b-8d5ae6086ab9', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '6a0b3174-68fe-4aa4-9790-1e3d74327560', 'subtopic'::public.curated_course_node_type, 'Power and performance measures', 'The gist is to distinguish power from strength and select tests that are safe, meaningful, and practical.', 1),
  ('6fd4fc1c-8c44-4779-8712-eedf21cc03bc', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '4721a20f-a82f-49fb-bf0b-8d5ae6086ab9', 'concept'::public.curated_course_node_type, 'Vertical jump, broad jump, medicine-ball throw, and sprint-related measures', null, 0),
  ('fa96fd04-e6bf-4fd1-ab5f-1f9117511c4a', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '4721a20f-a82f-49fb-bf0b-8d5ae6086ab9', 'concept'::public.curated_course_node_type, 'Force, velocity, rate of force development, and power concepts', null, 1),
  ('c951e3b6-b177-4333-bdac-f4be6e4fb355', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '4721a20f-a82f-49fb-bf0b-8d5ae6086ab9', 'concept'::public.curated_course_node_type, 'Athlete versus general-population test selection', null, 2),
  ('c203f7fb-21f3-4bc9-a52b-3ef4311afd42', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '4721a20f-a82f-49fb-bf0b-8d5ae6086ab9', 'concept'::public.curated_course_node_type, 'Norms, asymmetry, fatigue, and monitoring change', null, 3),
  ('e76d0054-0eeb-4c98-9e81-7568f92efbef', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Flexibility, mobility, and range-of-motion assessment', 'Flexibility and mobility tests are useful only when they connect to function, comfort, or goals. This section shows students how to assess range without turning every difference into a problem.', 6),
  ('c617cc3a-6885-47a5-94d5-bdcae1abc284', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'e76d0054-0eeb-4c98-9e81-7568f92efbef', 'subtopic'::public.curated_course_node_type, 'Flexibility and range-of-motion testing', 'Students learn standardized methods for common field and goniometric measures.', 0),
  ('565e9479-83e0-406c-ab35-4f22ca1bb769', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'c617cc3a-6885-47a5-94d5-bdcae1abc284', 'concept'::public.curated_course_node_type, 'Sit-and-reach, shoulder mobility, trunk rotation, and ankle mobility tests', null, 0),
  ('ce238c3d-c21e-4ec1-857c-bc87ab8eb179', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'c617cc3a-6885-47a5-94d5-bdcae1abc284', 'concept'::public.curated_course_node_type, 'Active versus passive range of motion', null, 1),
  ('8fa9cf27-89f2-4682-8536-25b4552fa792', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'c617cc3a-6885-47a5-94d5-bdcae1abc284', 'concept'::public.curated_course_node_type, 'Goniometer landmarks, alignment, and recording', null, 2),
  ('ec18e839-8f31-43c8-ba6b-f6d1d9d3dc5a', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'c617cc3a-6885-47a5-94d5-bdcae1abc284', 'concept'::public.curated_course_node_type, 'Warm-up effects, pain, compensations, and measurement error', null, 3),
  ('14025f5f-04c4-4a7e-a771-32db47b4310a', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'e76d0054-0eeb-4c98-9e81-7568f92efbef', 'subtopic'::public.curated_course_node_type, 'Interpreting mobility constraints', 'The point is to decide whether a limitation matters for the person''s activity goals and safety.', 1),
  ('4d398a76-5f2f-4f13-affa-839e3429554c', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '14025f5f-04c4-4a7e-a771-32db47b4310a', 'concept'::public.curated_course_node_type, 'Mobility versus stability versus motor control distinctions', null, 0),
  ('5c71baca-0aec-4935-a302-0ede09d1bcc0', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '14025f5f-04c4-4a7e-a771-32db47b4310a', 'concept'::public.curated_course_node_type, 'Sport, occupational, aging, and daily-living relevance', null, 1),
  ('34fd6db0-373b-4a54-82b4-9d9e71ab5b7b', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '14025f5f-04c4-4a7e-a771-32db47b4310a', 'concept'::public.curated_course_node_type, 'Hypermobility, pain flags, and referral considerations', null, 2),
  ('8f33734a-b2d1-404b-a068-a3f112228c23', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '14025f5f-04c4-4a7e-a771-32db47b4310a', 'concept'::public.curated_course_node_type, 'Linking mobility findings to exercise selection and progression', null, 3),
  ('1e275e59-83a7-4a1d-a320-7f7de7ae5c46', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Functional movement, balance, and movement-quality screening', 'Movement screening helps describe how a person moves, but it must be used carefully. This section builds practical observation skills without overstating predictive power.', 7),
  ('d4e2692b-f97a-4ce3-8931-e0b6303e130f', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '1e275e59-83a7-4a1d-a320-7f7de7ae5c46', 'subtopic'::public.curated_course_node_type, 'Movement screening and task analysis', 'Students learn to observe movement patterns, compensation, control, and task performance in a structured way.', 0),
  ('b40f9868-eb9b-4f17-9487-52ec57afdd39', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'd4e2692b-f97a-4ce3-8931-e0b6303e130f', 'concept'::public.curated_course_node_type, 'Squat, hinge, lunge, push, pull, carry, gait, and reach tasks', null, 0);
