  ('74c852d3-c2f7-48d2-88c6-363a6152938c', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'd4e2692b-f97a-4ce3-8931-e0b6303e130f', 'concept'::public.curated_course_node_type, 'Video, checklists, and inter-rater reliability', null, 3),
  ('426a9d55-e14d-4d13-970c-c40c3905b585', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '1e275e59-83a7-4a1d-a320-7f7de7ae5c46', 'subtopic'::public.curated_course_node_type, 'Balance, fall risk, and functional performance', 'The gist is to assess abilities that matter for daily life, sport, and safe exercise participation.', 1),
