  ('613979e4-6e8e-46d2-81c2-fa94e33e6056', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '426a9d55-e14d-4d13-970c-c40c3905b585', 'concept'::public.curated_course_node_type, 'Timed Up and Go, chair stand, gait speed, and stair or step tasks', null, 1),
  ('e700abad-ea36-4a81-b988-120dd3c4892b', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '426a9d55-e14d-4d13-970c-c40c3905b585', 'concept'::public.curated_course_node_type, 'Older adult, clinical, and return-to-activity contexts', null, 2),
  ('7030f6a2-bd71-4fb2-8f1f-26c450f61acc', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '426a9d55-e14d-4d13-970c-c40c3905b585', 'concept'::public.curated_course_node_type, 'Referral and program modification based on functional findings', null, 3),
  ('ae952e23-8332-40d4-8c03-3c8673675000', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Special populations, accessibility, and inclusive testing modifications', 'World-class assessment adapts to the person. This section teaches students to modify testing while preserving safety, dignity, and the meaning of the result.', 8),
  ('712eb5dd-4d7d-4f28-801c-0589ad9064ad', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'ae952e23-8332-40d4-8c03-3c8673675000', 'subtopic'::public.curated_course_node_type, 'Population-specific testing considerations', 'Students learn how age, health status, training status, and life stage influence test choice and interpretation.', 0),
  ('c0e534c0-c725-43e5-8d33-86c272253960', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '712eb5dd-4d7d-4f28-801c-0589ad9064ad', 'concept'::public.curated_course_node_type, 'Youth, older adults, pregnant and postpartum clients, and novice exercisers', null, 0),
  ('1b1c64fa-efb6-4bd8-92af-0a8e69add213', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '712eb5dd-4d7d-4f28-801c-0589ad9064ad', 'concept'::public.curated_course_node_type, 'Athletes, tactical populations, and high-performance contexts', null, 1),
  ('150dd369-4537-45ca-9e29-bc06322ba2f9', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '712eb5dd-4d7d-4f28-801c-0589ad9064ad', 'concept'::public.curated_course_node_type, 'Cardiometabolic, pulmonary, neurologic, musculoskeletal, and pain conditions', null, 2),
  ('f0d92450-feb9-4cc7-b028-1e638872d6a6', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '712eb5dd-4d7d-4f28-801c-0589ad9064ad', 'concept'::public.curated_course_node_type, 'Medication effects, fatigue, heat sensitivity, and recovery needs', null, 3),
  ('5a686de3-7ce3-4c65-9354-526061581bc7', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'ae952e23-8332-40d4-8c03-3c8673675000', 'subtopic'::public.curated_course_node_type, 'Accessibility and inclusive testing design', 'The point is to remove avoidable barriers and document accommodations clearly.', 1),
  ('5ef3c64e-ac5a-4121-96dd-79ffdba5efd4', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5a686de3-7ce3-4c65-9354-526061581bc7', 'concept'::public.curated_course_node_type, 'Disability-informed communication and participant preference', null, 0),
  ('d0f28d5a-e341-4e88-8638-a6e17b5694ec', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5a686de3-7ce3-4c65-9354-526061581bc7', 'concept'::public.curated_course_node_type, 'Equipment access, transfer safety, sensory needs, and space layout', null, 1),
  ('e9e46fcb-7637-4238-9cf3-c91cb63cd2cf', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5a686de3-7ce3-4c65-9354-526061581bc7', 'concept'::public.curated_course_node_type, 'Modified protocols, alternative outcomes, and comparability limits', null, 2),
  ('db915537-dd24-4df3-b7e4-c4b66a7a96e0', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5a686de3-7ce3-4c65-9354-526061581bc7', 'concept'::public.curated_course_node_type, 'Culturally responsive practice and health-literacy adaptation', null, 3),
  ('ab56e507-baea-40e4-828c-b8230f6638a2', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Fitness profiles, norms, reliability, validity, and interpretation of results', 'A strong assessor can integrate results, not just report numbers. This section develops the measurement literacy needed to build meaningful fitness profiles.', 9),
  ('81ce34ba-b817-4058-9aca-5a7957e3a74c', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'ab56e507-baea-40e4-828c-b8230f6638a2', 'subtopic'::public.curated_course_node_type, 'Measurement quality and norms', 'Students learn how to judge whether a score is trustworthy, comparable, and useful.', 0),
  ('309f168c-cace-47b9-a9eb-2270772b56b0', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '81ce34ba-b817-4058-9aca-5a7957e3a74c', 'concept'::public.curated_course_node_type, 'Reliability, validity, sensitivity, specificity, and standard error of measurement', null, 0),
  ('ad9e48c5-1823-44f2-8a2d-8d71f9aecf73', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '81ce34ba-b817-4058-9aca-5a7957e3a74c', 'concept'::public.curated_course_node_type, 'Norm-referenced versus criterion-referenced standards', null, 1),
  ('06875246-a764-491b-86bb-d7792da4240a', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '81ce34ba-b817-4058-9aca-5a7957e3a74c', 'concept'::public.curated_course_node_type, 'Percentiles, z-scores, minimal detectable change, and meaningful change', null, 2),
  ('ce227d4e-3f8d-499f-a0a1-300681517641', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '81ce34ba-b817-4058-9aca-5a7957e3a74c', 'concept'::public.curated_course_node_type, 'Protocol specificity and limits of cross-test comparison', null, 3),
  ('3f3c6b15-8ce4-42ad-b006-120d0c3b328a', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', 'ab56e507-baea-40e4-828c-b8230f6638a2', 'subtopic'::public.curated_course_node_type, 'Integrated fitness profiles', 'The gist is to synthesize multiple measures into a coherent picture that guides decisions.', 1),
  ('82e0e1d5-c8e8-4364-8a15-1189d5fb6098', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '3f3c6b15-8ce4-42ad-b006-120d0c3b328a', 'concept'::public.curated_course_node_type, 'Health-related and performance-related fitness components', null, 0),
  ('8ae00148-4714-4ea1-bd31-1cace5af1b90', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '3f3c6b15-8ce4-42ad-b006-120d0c3b328a', 'concept'::public.curated_course_node_type, 'Strengths, limitations, priority needs, and uncertainty', null, 1),
  ('890597fc-dd73-4609-bc2b-a35b55303997', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '3f3c6b15-8ce4-42ad-b006-120d0c3b328a', 'concept'::public.curated_course_node_type, 'Risk, readiness, preferences, and environmental constraints', null, 2),
  ('fcfbbca0-f85a-49cb-bf73-374d7c5f29b0', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '3f3c6b15-8ce4-42ad-b006-120d0c3b328a', 'concept'::public.curated_course_node_type, 'Visual summaries, dashboards, and plain-language interpretation', null, 3),
  ('5bcf2436-86ab-4773-ae27-0588364b8392', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', null, 'topic'::public.curated_course_node_type, 'Goal setting, behavior change, feedback, and client communication', 'Assessment results only matter when people can understand and act on them. This section teaches students to turn data into collaborative goals and supportive feedback.', 10),
  ('9082be66-55cd-42e9-b4dc-dfb479348262', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5bcf2436-86ab-4773-ae27-0588364b8392', 'subtopic'::public.curated_course_node_type, 'Client feedback and health communication', 'Students learn to explain results in ways that are accurate, motivating, and respectful.', 0),
  ('90942a96-01f3-46c6-8d25-a9cd748ac9cc', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '9082be66-55cd-42e9-b4dc-dfb479348262', 'concept'::public.curated_course_node_type, 'Plain-language summaries, teach-back, and checking understanding', null, 0),
  ('1e9e87b2-36ca-4c18-a4bf-a93f0dc91a2b', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '9082be66-55cd-42e9-b4dc-dfb479348262', 'concept'::public.curated_course_node_type, 'Avoiding fear-based, stigmatizing, or overconfident claims', null, 1),
  ('b3e9b894-fbce-42ab-ac54-1273647e6c2a', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '9082be66-55cd-42e9-b4dc-dfb479348262', 'concept'::public.curated_course_node_type, 'Strengths-first feedback and autonomy-supportive recommendations', null, 2),
  ('5ca0faae-b614-4520-a38b-8a322497cdbd', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '9082be66-55cd-42e9-b4dc-dfb479348262', 'concept'::public.curated_course_node_type, 'Communicating uncertainty, limitations, and next steps', null, 3),
  ('181140b1-be48-4637-93f9-67f37b719865', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '5bcf2436-86ab-4773-ae27-0588364b8392', 'subtopic'::public.curated_course_node_type, 'Goal setting and behavior change', 'The point is to connect assessment results with goals the client values and can sustain.', 1),
  ('fcf70431-da4f-4085-9059-bba288c03c36', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '181140b1-be48-4637-93f9-67f37b719865', 'concept'::public.curated_course_node_type, 'SMART goals, outcome/process goals, and habit targets', null, 0),
  ('06e7e3ec-2f5b-401a-aa26-8a7c94cd6704', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '181140b1-be48-4637-93f9-67f37b719865', 'concept'::public.curated_course_node_type, 'Motivational interviewing basics and readiness for change', null, 1),
  ('5b91107e-c7cc-40f7-9325-3bd8958da259', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '181140b1-be48-4637-93f9-67f37b719865', 'concept'::public.curated_course_node_type, 'Self-monitoring, accountability, barriers, and supports', null, 2);
