  ('e3be3d4c-d3be-492d-9525-7bb62413b956', 'f4c8a2d7-1b59-4e06-9a31-6d0e5c3b8f17', '7c8a6d7c-e2f6-4397-a63b-292463f478a5', 'subtopic'::public.curated_course_node_type, 'FITT-VP program design from results', 'Students learn to translate assessment priorities into safe and progressive exercise plans.', 0),
